using CapitalPos.Domain; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace CapitalPos.Infrastructure.Persistence.Configurations;
public sealed class MovimientoInventarioConfiguration : IEntityTypeConfiguration<MovimientoInventario> { public void Configure(EntityTypeBuilder<MovimientoInventario> b) { b.ToTable("movimientos_inventario"); b.HasKey(x=>x.Id); b.Property(x=>x.Id).ValueGeneratedNever(); b.Property(x=>x.TipoMovimiento).HasConversion<string>().HasMaxLength(30).IsRequired(); b.Property(x=>x.Cantidad).HasPrecision(18,3); b.Property(x=>x.StockAnterior).HasPrecision(18,3); b.Property(x=>x.StockPosterior).HasPrecision(18,3); b.Property(x=>x.ReferenciaTipo).HasMaxLength(50); b.Property(x=>x.Motivo).HasMaxLength(500); b.HasIndex(x=>new { x.EmpresaId,x.SedeId,x.ProductoId,x.ProductoVarianteId,x.FechaCreacion }); } }
